        FROM records
        ORDER BY created_at DESC
    `)
    if err != nil {
        return nil, err
    }
    defer rows.Close()

    resp := &ListRecordsResponse{}
    for rows.Next() {
        rec := &Record{}
        if err := rows.Scan(&rec.ID, &rec.Data, &rec.CreatedAt); err != nil {
